UCLASS()
class URBANLIFE_API AOpenWorldCharacter : public ACharacter
{
    GENERATED_BODY()

public:
    AOpenWorldCharacter();

protected:
    virtual void BeginPlay() override;

    UPROPERTY(VisibleAnywhere, BlueprintReadOnly)
    TObjectPtr<USpringArmComponent> CameraBoom;

    UPROPERTY(VisibleAnywhere, BlueprintReadOnly)
    TObjectPtr<UCameraComponent> FollowCamera;

    UPROPERTY(EditDefaultsOnly, Category=\"Input\")
    TObjectPtr<UInputMappingContext> DefaultMapping;

    UPROPERTY(EditDefaultsOnly, Category=\"Input\")
    TObjectPtr<UInputAction> MoveAction;

    UPROPERTY(EditDefaultsOnly, Category=\"Input\")
    TObjectPtr<UInputAction> LookAction;

    UPROPERTY(EditDefaultsOnly, Category=\"Input\")
    TObjectPtr<UInputAction> JumpAction;

    UPROPERTY(EditDefaultsOnly, Category=\"Input\")
    TObjectPtr<UInputAction> InteractAction;

    void Move(const struct FInputActionValue@COMMENT_BODY@ Value);
    void Look(const struct FInputActionValue@COMMENT_BODY@ Value);
    void Interact();

    virtual void SetupPlayerInputComponent(
        UInputComponent* PlayerInputComponent) override;

public:
    UFUNCTION(BlueprintCallable, Category=\"Player\")
    void SetRunning(bool bRunning);
};

#include \"OpenWorldCharacter.h\"

#include \"Camera/CameraComponent.h\"
#include \"GameFramework/SpringArmComponent.h\"
#include \"GameFramework/CharacterMovementComponent.h\"

#include \"EnhancedInputComponent.h\"
#include \"EnhancedInputSubsystems.h\"
#include \"InputActionValue.h\"

#include \"Engine/LocalPlayer.h\"
#include \"MissionTarget.h\"

AOpenWorldCharacter::AOpenWorldCharacter()
{
    PrimaryActorTick.bCanEverTick = true;

    CameraBoom = CreateDefaultSubobject<USpringArmComponent>(
        TEXT(\"CameraBoom\"));

    CameraBoom->SetupAttachment(RootComponent);
    CameraBoom->TargetArmLength = 350.0f;
    CameraBoom->bUsePawnControlRotation = true;

    FollowCamera = CreateDefaultSubobject<UCameraComponent>(
        TEXT(\"FollowCamera\"));

    FollowCamera->SetupAttachment(
        CameraBoom,
        USpringArmComponent::SocketName);

    FollowCamera->bUsePawnControlRotation = false;

    bUseControllerRotationYaw = false;

    GetCharacterMovement()->bOrientRotationToMovement = true;
    GetCharacterMovement()->RotationRate =
        FRotator(0.0f, 540.0f, 0.0f);

    GetCharacterMovement()->MaxWalkSpeed = 350.0f;
}

void AOpenWorldCharacter::BeginPlay()
{
    Super::BeginPlay();

    if (APlayerController* PC =
        Cast<APlayerController>(GetController()))
    {
        if (ULocalPlayer* LP = PC->GetLocalPlayer())
        {
            if (auto* Subsystem =
                LP->GetSubsystem<
                UEnhancedInputLocalPlayerSubsystem>())
            {
                if (DefaultMapping)
                {
                    Subsystem->AddMappingContext(
                        DefaultMapping, 0);
                }
            }
        }
    }
}

void AOpenWorldCharacter::Move(
    const FInputActionValue@COMMENT_BODY@ Value)
{
    FVector2D Movement = Value.Get<FVector2D>();

    if (!Controller) return;

    const FRotator Rotation =
        Controller->GetControlRotation();

    const FRotator YawRotation(
        0, Rotation.Yaw, 0);

    const FVector Forward =
        FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X);

    const FVector Right =
        FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);

    AddMovementInput(Forward, Movement.Y);
    AddMovementInput(Right, Movement.X);
}

